#!/usr/bin/env python3
"""Run unchanged Xcode with the source bitmap context and coherent kernel profile."""
from pathlib import Path
from datetime import datetime,timezone
import argparse,hashlib,json,runpy,subprocess
root=Path(__file__).resolve().parent.parent
parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('mode',choices=['version','showsdks']);parser.add_argument('--log-enablement',action='store_true');parser.add_argument('--native-message',action='store_true');parser.add_argument('--log-hooks',action='store_true');parser.add_argument('--container-persona',action='store_true');parser.add_argument('--mobilegestalt',action='store_true');parser.add_argument('--native-mobilegestalt',action='store_true');parser.add_argument('--runnable-archs',action='store_true');parser.add_argument('--native-imageio',action='store_true');parser.add_argument('--native-combine',action='store_true');parser.add_argument('--source-fsevents',action='store_true');parser.add_argument('--fsevents-flush',action='store_true');parser.add_argument('--foundation-coherent',action='store_true');args=parser.parse_args()
name='foundation-coherent' if args.foundation_coherent else 'fsevents-flush' if args.fsevents_flush else 'fsevents-source' if args.source_fsevents else 'combine-native' if args.native_combine else 'imageio-native' if args.native_imageio else 'runnable-archs' if args.runnable_archs else 'mobilegestalt-native' if args.native_mobilegestalt else 'mobilegestalt-source' if args.mobilegestalt else 'container-persona' if args.container_persona else 'log-hooks' if args.log_hooks else 'native-log-message' if args.native_message else 'log-enablement' if args.log_enablement else 'native-layer-context'
stem=('foundation-coherent-xcode-' if args.foundation_coherent else 'fsevents-flush-xcode-' if args.fsevents_flush else 'fsevents-source-xcode-' if args.source_fsevents else 'combine-native-xcode-' if args.native_combine else 'imageio-native-xcode-' if args.native_imageio else 'runnable-archs-xcode-' if args.runnable_archs else 'mobilegestalt-native-xcode-' if args.native_mobilegestalt else 'mobilegestalt-xcode-' if args.mobilegestalt else 'container-persona-xcode-' if args.container_persona else 'log-hooks-xcode-' if args.log_hooks else 'native-message-xcode-' if args.native_message else 'log-enablement-xcode-' if args.log_enablement else 'native-layer-xcode-')+args.mode
