r=subprocess.run(c,cwd=root,env=m['environment'](p),capture_output=True,text=True);log='logs/'+stem+'.log';(root/log).write_text(r.stdout+r.stderr);digest=lambda s:hashlib.sha256((root/s).read_bytes()).hexdigest()
