record={**p,'checked_at':datetime.now(timezone.utc).isoformat(),'command':c,'exit_status':r.returncode,'log':log,'log_sha256':digest(log),'diagnostic':r.stdout+r.stderr,'original_xcodebuild_sha256':digest(original),'full_xcode_build_ready':False,'signing_ready':False}
(root/('artifacts/'+stem+'.json')).write_text(json.dumps(record,indent=2)+'\n');print(r.stdout+r.stderr,end='');raise SystemExit(r.returncode)
